import { makeSlug } from "./slug.js"

interface Link {
  url: string
  expiresAt?: number
}

/** Links in memory, by slug. */
export class LinkStore {
  private links = new Map<string, Link>()

  /** Store a URL and return its slug. With `ttlMs`, the link expires that long from now. */
  put(url: string, ttlMs?: number): string {
    const slug = makeSlug(url)
    this.links.set(slug, {
      url,
      ...(ttlMs !== undefined ? { expiresAt: Date.now() + ttlMs } : {}),
    })
    return slug
  }

  /** The URL for a slug, or undefined when there is none or it has expired. */
  get(slug: string): string | undefined {
    const link = this.links.get(slug)
    if (!link) return undefined
    if (link.expiresAt !== undefined && Date.now() >= link.expiresAt) return undefined
    return link.url
  }
}


